import torch

for name in ['SGD', 'Adagrad', 'RMSprop', 'Adam']:
    w = torch.tensor(1.0, requires_grad=True)
    if name == 'SGD':
        opt = torch.optim.SGD([w], lr=0.1)
    elif name == 'Adagrad':
        opt = torch.optim.Adagrad([w], lr=0.1)
    elif name == 'RMSprop':
        opt = torch.optim.RMSprop([w], lr=0.1, alpha=0.9)  # alpha = 감쇠율 ρ (모멘텀 α 아님)
    else:
        opt = torch.optim.Adam([w], lr=0.1)
    opt.zero_grad()
    (w ** 2).backward()
    opt.step()
    print(name, round(w.item(), 4))

