import re
import torch

def simple_tokenize(s):
    return re.findall(r"\b\w+\b", s.lower())

specials = ["<unk>", "<pad>"]
itos = specials + ["the", "movie", "good", "bad"]
stoi = {w: i for i, w in enumerate(itos)}
UNK_IDX = stoi["<unk>"]

def text_pipeline(x):
    ids = [stoi.get(tok, UNK_IDX) for tok in simple_tokenize(x)]
    return torch.tensor(ids, dtype=torch.long)

print(text_pipeline("The movie was GOOD!").tolist())
print(simple_tokenize("didn't"))
print(len(stoi))

import torch.nn as nn

conv_base = nn.Sequential(nn.Conv2d(3, 4, kernel_size=3), nn.ReLU())

def n_trainable(m):
    return sum(p.numel() for p in m.parameters() if p.requires_grad)

print(n_trainable(conv_base))
conv_base.eval()
print(n_trainable(conv_base))
for p in conv_base.parameters():
    p.requires_grad = False
print(n_trainable(conv_base))

import torch.nn as nn

class Mini(nn.Module):
    def __init__(self):
        super().__init__()
        self.layer3 = nn.Conv2d(4, 8, kernel_size=3, padding=1)
        self.layer4 = nn.Conv2d(8, 8, kernel_size=3, padding=1)
        self.fc = nn.Linear(8, 1)

model = Mini()
for name, p in model.named_parameters():
    if not name.startswith("fc."):
        p.requires_grad = False          # freeze everything except fc
for p in model.layer4.parameters():
    p.requires_grad = True               # unfreeze ONLY layer4
print([name for name, p in model.named_parameters() if p.requires_grad])
print(sum(p.numel() for p in model.parameters() if p.requires_grad))
